 88	\begin{definition}[Line-point distributions]\label{def:line-point-dist}
 89		\lean{MIPStarRE.QPBT.LineKind, MIPStarRE.QPBT.LineDesc}
 90		\lean{MIPStarRE.QPBT.aLinePointDist, MIPStarRE.QPBT.dLinePointDist}
 91		\lean{MIPStarRE.QPBT.linePointDist}
 92		\lean{MIPStarRE.QPBT.aLinePointDist_isProbability}
 93		\lean{MIPStarRE.QPBT.dLinePointDist_isProbability}
 94		\lean{MIPStarRE.QPBT.linePointDist_isProbability}
 95		\leanok
 96		\uses{def:ld-question-distribution, lem:alnf, lem:dlnf}
 97		The \emph{axis line-point distribution} $D_{\mathsf{ALine}}$ is the distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$ over pairs $(\ell = (u_0,e_i),\, u)$, where we omit the $0$ components for simplicity. The \emph{diagonal line-point distribution} $D_{\mathsf{DLine}}$ is the distribution $\mu_{L_{\mathsf{DLine}}, L_{\mathsf{Point}}}$ over pairs $(\ell = (u_0,s,v),\, u)$. The \emph{line-point distribution} $D_{\mathsf{Line}}$ is the equal mixture of the two: with probability $\tfrac12$ output a sample from $D_{\mathsf{ALine}}$, and with probability $\tfrac12$ output a sample from $D_{\mathsf{DLine}}$.
 98	\end{definition}
