136	Quantum soundness of a version of the classical low-degree test for polynomials of low \emph{total} degree was claimed by Natarajan and Vidick, building on an analysis of a three-prover version of the test by Vidick; there is a known gap in the soundness analysis of that test, and it is not used here. Instead, the construction relies on the low \emph{individual} degree test, whose quantum soundness is proved in~\cite{Ji2020LowIndividualDegree} and generalized in~\cite{Ji2021Quantum}. The statement below is the form most directly useful in what follows.
137	
138	% The paper states this result in a theorem environment with the label lem:ld-soundness.
139	% We keep both the environment and the label verbatim for cross-reference fidelity.
140	\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\label{lem:ld-soundness}
141		\lean{MIPStarRE.QPBT.deltaLd, MIPStarRE.QPBT.exists_ld_soundness}
142		\leanok
143		\uses{def:ld-game, def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:projective-strategy-general, def:tensor-product-value, def:consistency, def:bracket}
144		There exists a function
145		\[
146			\delta_{\mathrm{ld}}(\eps, q, m, d, k) = a\,(dmk)^a \bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
147		\]
148		for universal constants $a \ge 1$ and $0 < b \le 1$ such that the following holds. For all $\eps > 0$ and every parameter tuple $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game} (so $m, d, k \ge 1$, $q$ is an admissible field size, and $m$ divides $q$), and for all projective strategies $(\psi, A, B)$ that succeed with probability at least $1-\eps$ in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$, there exist measurements
149		\[
150			G^w \in \mathrm{PolyMeas}(m,q,d,k)
151		\]
152		on $\hilb_w$ for $w \in \{\mathrm A,\mathrm B\}$, where by slight abuse of notation $m$, $q$, $d$ denote the constant tuples $(m,\ldots,m)$, $(q,\ldots,q)$, $(d,\ldots,d)$ of length $k$, such that
153		\begin{align*}
154			A^{\mathsf{Point},\, u}_{a_1,\ldots,a_k} \ot I_{\mathrm B}
155			&\simeq_{\delta_{\mathrm{ld}}}
156			I_{\mathrm A} \ot G^{\mathrm B}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]}\;,\\
157			G^{\mathrm A}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]} \ot I_{\mathrm B}
158			&\simeq_{\delta_{\mathrm{ld}}}
159			I_{\mathrm A} \ot B^{\mathsf{Point},\, u}_{a_1,\ldots,a_k}\;,\\
160			G^{\mathrm A}_{g_1,\ldots,g_k} \ot I_{\mathrm B}
161			&\simeq_{\delta_{\mathrm{ld}}}
162			I_{\mathrm A} \ot G^{\mathrm B}_{g_1,\ldots,g_k}\;,
163		\end{align*}
164		where $\delta_{\mathrm{ld}} = \delta_{\mathrm{ld}}(\eps,q,m,d,k)$, all three relations are the state-dependent consistency $\simeq$ of Definition~\ref{def:consistency} with respect to the state $\ket{\psi}$, and the bracket notation for post-processed outcomes is that of Definition~\ref{def:bracket}. The first two relations hold on average over the uniform distribution on $u \in \F_q^m$; no question distribution is associated with the third.
165	\end{theorem}
166	\begin{proof}
167		\uses{def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:povm-distance}
168		Let $\Sigma = \F_q$ and let $\code \subseteq \Sigma^q$ be the Reed--Solomon code of degree $d$: the set of all $(p(x_1),\ldots,p(x_q))$ where $p\colon \F_q \to \F_q$ is a univariate polynomial of degree at most $d$ and $x_1,\ldots,x_q$ enumerate $\F_q$. We may assume $d < q$. In the opposite regime the statement is immediate: for $d \ge q$ the prefactor gives $\delta_{\mathrm{ld}} \ge a\,(dmk)^a\, q^{-b} \ge q^{a-b} \ge 1$, using $m, k \ge 1$, while the quantity bounded in Definition~\ref{def:consistency} never exceeds $4$ for families of POVM elements: $\sum_a \lVert (A_a \ot I - I \ot B_a)\ket{\psi}\rVert^2 \le 2\sum_a \bigl(\bra{\psi} A_a^2 \ot I \ket{\psi} + \bra{\psi} I \ot B_a^2 \ket{\psi}\bigr) \le 4$, using $0 \le M_a^2 \le M_a$ and $\sum_a M_a = \Id$ for POVM elements, so the three relations hold for an arbitrary choice of $G^w \in \mathrm{PolyMeas}(m,q,d,k)$. For $d < q$, evaluation is injective on polynomials of degree at most $d$ and a nonzero polynomial of degree at most $d$ vanishes at no more than $d$ of the $q$ points, so $\code$ is a linear $[q,\, d+1,\, q-d]_\Sigma$ code.
